  const bundle=await peopleCbsProject(api,rawEntries,rawCharacter,chat,marker),{entries,character}=bundle;
  const sources=[],cardContent=[['name',character?.name],['description',character?.desc??character?.description],['personality',character?.personality],['scenario',character?.scenario],['firstMessage',character?.firstMessage??character?.first_message]].filter(([,value])=>typeof value==='string'&&value.trim()).map(([key,value])=>`${key}: ${value}`).join('\n');
  if(cardContent)sources.push({ref:'source:people_card',kind:'card',label:peopleImportText(character?.name||'Current card',160),keys:[],content:peopleImportText(cardContent,PEOPLE_IMPORT_LIMITS.sourceChars),discovery:mode==='all'});
  if(mode==='active'&&recent.trim())sources.push({ref:'source:people_recent_chat',kind:'recent_chat',label:'Recent active chat',keys:[],content:peopleImportText(recent,PEOPLE_IMPORT_LIMITS.sourceChars),discovery:true});
  for(let index=0;index<entries.length;index++){
    const entry=entries[index];if(peopleImportDisabled(entry))continue;if(mode==='lore-active'&&!peopleImportAlways(entry))continue;const content=peopleImportEntryContent(entry);if(!content)continue;const keys=peopleImportKeys(entry),label=peopleImportText(entry.comment??entry.name??entry.displayName??`Lore ${index+1}`,160);sources.push({ref:`source:people_lore_${index}`,kind:'lore',label,keys,content,discovery:mode==='all'||mode==='lore-active'});
  }
