 if(!keywords.length)return people;
 const matched=people.map(person=>{const cited=sources.filter(source=>person.sourceRefs.includes(source.ref)),label=peopleImportAliasInSources(person.name,cited)?person.name:'';return{person,keywords:keywords.filter(keyword=>peopleSourceKeywordMatches({label,keys:person.aliases||[],content:''},[keyword]))};}),counts=new Map(keywords.map(keyword=>[keyword,matched.filter(item=>item.keywords.includes(keyword)).length]));
 return matched.filter(item=>item.keywords.length).map(({person,keywords:matches})=>({...person,inputKeywords:matches.filter(keyword=>counts.get(keyword)===1),metadataNotes:[...(person.metadataNotes||[]),...matches.filter(keyword=>counts.get(keyword)>1).map(keyword=>'여러 인물과 일치한 검색어는 검색에만 사용하고 별칭으로 추가하지 않았습니다: '+keyword)]}));
