  begin(stage,total){this.applyReport=null;this.pendingSave=null;this.sourceValidation=null;this.phase='running';this.stage=stage;this.completed=0;this.total=total;this.error='';this.candidates=[];this.selected.clear();this.startedAt=Date.now();this.cancelRequested=false;this.sexualField='';this.sexualDocumentId='';this.abortController=new AbortController();this.interval=this.scheduler.setInterval?.(()=>this.emit(),250)||null;this.emit();}
  finish(){if(this.interval!==null)this.scheduler.clearInterval?.(this.interval);this.interval=null;this.abortController=null;this.elapsedMs=Date.now()-this.startedAt;this.emit();}
  cancel(){if(this.phase!=='running')return;this.cancelRequested=true;this.abortController?.abort();this.phase='cancelled';this.stage='사용자 취소';this.emit();}
